// Lore : lore\GRANDE-TRAME.md § 3 (acte IV) et lore\BIBLE-CANON.md (Hôtes, Astréens, Aurélien, Tombeau du Premier Hôte).
// Écrit le 24/11/2026. Tout est préfixé a4_ (quêtes, PNJ, monstres, apparitions, points).
// Suite des quêtes l_le_pacte_des_deux_ciels / o_le_pacte_des_deux_ciels (la-marche.js). Suite : acte5-cimes.js.
// Réponses gardées : a4-presentation (banniere|marque), a4-loyaute (capitaine|envoye), a4-secret (taire|reveler),
//                    a4-kesh (croire|livrer), a4-commerce (refuser|vendre).
// Points : coordonnées réelles du continent (sol lu dans continent.dat ; places de village à Y 80 ; sites d'après sites-etat.yml).

// Récompenses : principale k = 1, annexe k = 0,85, contrat k = 0,45.
const XP = (lv, k = 1) => Math.round(7.9 * lv * lv * k / 10) * 10;
const OR = (lv, k = 1) => Math.round(0.79 * lv * lv * k / 5) * 5;

// Les deux versions d'une quête principale. S.p = 'l' | 'o'.
const SIDES = {
  l: { p: 'l', f: 'lumiere', env: 'a4_aldren', autre: 'a4_vesper', cap: 'a4_helis', ennemi: 'a4_lame_ombre', marche: 'aldren',
    pacte: 'l_le_pacte_des_deux_ciels' },
  o: { p: 'o', f: 'ombre', env: 'a4_vesper', autre: 'a4_aldren', cap: 'a4_sarn', ennemi: 'a4_lame_aube', marche: 'vesper',
    pacte: 'o_le_pacte_des_deux_ciels' },
};
const duo = build => [build(SIDES.l), build(SIDES.o)];
const T = (S, l, o) => (S.p === 'l' ? l : o);
const id = (S, n) => `a4_${S.p}_${n}`;

